+++ b/src/directedGraph.js
@@ -0,0 +1,203 @@
+'use strict';
+
+class DirectedGraph {
+	constructor() {
+		this._adjacency = new Map();
+		this._labels = new Map();
+		this._componentMap = new Map();
+		this._components = [];
+		this._dirty = true;
+	}
+
+	addVertex(vertex) {
+		if (!this._adjacency.has(vertex)) {
+			this._adjacency.set(vertex, new Set());
+			this._dirty = true;
+		}
+	}
+
+	addArc(from, to) {
+		this.addVertex(from);
+		this.addVertex(to);
+		if (!this._adjacency.get(from).has(to)) {
+			this._adjacency.get(from).add(to);
+			this._dirty = true;
+		}
+	}
+
+	removeVertex(vertex) {
+		if (!this._adjacency.has(vertex)) {
+			return;
+		}
+		this._adjacency.delete(vertex);
+		this._labels.delete(vertex);
+		for (const [, neighbors] of this._adjacency) {
+			neighbors.delete(vertex);
+		}
+		this._dirty = true;
+	}
+
+	removeArc(from, to) {
+		const neighbors = this._adjacency.get(from);
+		if (neighbors) {
+			neighbors.delete(to);
+			this._dirty = true;
+		}
+	}
+
+	hasVertex(vertex) {
+		return this._adjacency.has(vertex);
+	}
+
+	hasArc(from, to) {
+		const neighbors = this._adjacency.get(from);
+		return neighbors ? neighbors.has(to) : false;
+	}
+
+	getNeighbors(vertex) {
+		const neighbors = this._adjacency.get(vertex);
+		return neighbors ? Array.from(neighbors) : [];
+	}
+
+	setLabel(vertex, label) {
+		this.addVertex(vertex);
+		this._labels.set(vertex, label);
+	}
+
+	getLabel(vertex) {
+		return this._labels.get(vertex);
+	}
+
+	get vertexCount() {
+		return this._adjacency.size;
+	}
+
+	get arcCount() {
+		let count = 0;
+		for (const [, neighbors] of this._adjacency) {
+			count += neighbors.size;
+		}
+		return count;
+	}
+
+	get vertices() {
+		return Array.from(this._adjacency.keys());
+	}
+
+	_buildUndirectedNeighbors() {
+		const undirected = new Map();
+		for (const v of this._adjacency.keys()) {
+			undirected.set(v, new Set());
+		}
+		for (const [from, neighbors] of this._adjacency) {
+			for (const to of neighbors) {
+				undirected.get(from).add(to);
+				undirected.get(to).add(from);
+			}
+		}
+		return undirected;
+	}
+
+	_computeComponents() {
+		if (!this._dirty) {
+			return;
+		}
+		this._components = [];
+		this._componentMap = new Map();
+		const undirected = this._buildUndirectedNeighbors();
+		const visited = new Set();
+
+		for (const vertex of this._adjacency.keys()) {
+			if (visited.has(vertex)) {
+				continue;
+			}
+			const component = [];
+			const stack = [vertex];
+			while (stack.length > 0) {
+				const v = stack.pop();
+				if (visited.has(v)) {
+					continue;
+				}
+				visited.add(v);
+				component.push(v);
+				for (const neighbor of undirected.get(v)) {
+					if (!visited.has(neighbor)) {
+						stack.push(neighbor);
+					}
+				}
+			}
+			const componentIndex = this._components.length;
+			this._components.push(component);
+			for (const v of component) {
+				this._componentMap.set(v, componentIndex);
+			}
+		}
+		this._dirty = false;
+	}
+
+	getComponents() {
+		this._computeComponents();
+		return this._components.slice().map(c => c.slice());
+	}
+
+	get componentCount() {
+		this._computeComponents();
+		return this._components.length;
+	}
+
+	getComponentOf(vertex) {
+		this._computeComponents();
+		const idx = this._componentMap.get(vertex);
+		if (idx === undefined) {
+			return null;
+		}
+		return this._components[idx].slice();
+	}
+
+	getIsolates() {
+		const isolates = [];
+		for (const [vertex, neighbors] of this._adjacency) {
+			if (neighbors.size > 0) {
+				continue;
+			}
+			let hasIncoming = false;
+			for (const [, otherNeighbors] of this._adjacency) {
+				if (otherNeighbors.has(vertex)) {
+					hasIncoming = true;
+					break;
+				}
+			}
+			if (!hasIncoming) {
+				isolates.push(vertex);
+			}
+		}
+		return isolates;
+	}
+
+	toJSON() {
+		this._computeComponents();
+		const nodes = [];
+		const links = [];
+		for (const [vertex, neighbors] of this._adjacency) {
+			nodes.push({
+				id: vertex,
+				label: this._labels.get(vertex) || String(vertex),
+				component: this._componentMap.get(vertex),
+			});
+			for (const to of neighbors) {
+				links.push({ source: vertex, target: to });
+			}
+		}
+		return {
+			nodes,
+			links,
+			stats: {
+				vertices: this.vertexCount,
+				arcs: this.arcCount,
+				components: this.componentCount,
+			},
+		};
+	}
+}
+
+module.exports = DirectedGraph;

