+// Copy copies a bundle from one local OCI reference to another. Both source and
+// destination must be local (flipt://) references and must include a tag.
+// Returns the new bundle at the destination with correct metadata.
+func (s *Store) Copy(ctx context.Context, srcRef, destRef Reference) (Bundle, error) {
+	if srcRef.Reference.Reference == "" {
+		return Bundle{}, fmt.Errorf("source reference: %w", ErrMissingTag)
+	}
+	if destRef.Reference.Reference == "" {
+		return Bundle{}, fmt.Errorf("destination reference: %w", ErrMissingTag)
+	}
+	if srcRef.Scheme != SchemeFlipt {
+		return Bundle{}, fmt.Errorf("source reference must be a local (flipt://) reference for copy")
+	}
+	if destRef.Scheme != SchemeFlipt {
+		return Bundle{}, fmt.Errorf("destination reference must be a local (flipt://) reference for copy")
+	}
+
+	srcStore, err := s.getTarget(srcRef)
+	if err != nil {
+		return Bundle{}, err
+	}
+	destStore, err := s.getTarget(destRef)
+	if err != nil {
+		return Bundle{}, err
+	}
+
+	desc, err := oras.Copy(ctx,
+		srcStore,
+		srcRef.Reference.Reference,
+		destStore,
+		destRef.Reference.Reference,
+		oras.DefaultCopyOptions)
+	if err != nil {
+		return Bundle{}, err
+	}
+
+	bytes, err := content.FetchAll(ctx, destStore, desc)
+	if err != nil {
+		return Bundle{}, err
+	}
+	var manifest v1.Manifest
+	if err = json.Unmarshal(bytes, &manifest); err != nil {
+		return Bundle{}, err
+	}
+	createdAt, err := parseCreated(manifest.Annotations)
+	if err != nil {
+		return Bundle{}, err
+	}
+
+	return Bundle{
+		Digest:     desc.Digest,
+		Repository: destRef.Repository,
+		Tag:        destRef.Reference.Reference,
+		CreatedAt:  createdAt,
+	}, nil
+}
