+	user_id varchar(255) not null,
+	key varchar(255) not null,
+	value varchar(255) default '' not null,
+	primary key (user_id, key),
+	foreign key (user_id) references user(id) on delete cascade
+);
+
+create index if not exists user_props_user_id on user_props (user_id);
+`)
+	if err != nil {
+		return err
+	}
+
+	rows, err := tx.Query("select id, value from property where id like ?", lastFMSessionKeyPrefix+"%")
+	if err != nil {
+		return err
+	}
+	defer rows.Close()
+
+	for rows.Next() {
+		var id, value string
+		if err := rows.Scan(&id, &value); err != nil {
+			return err
+		}
+		userID := strings.TrimPrefix(id, lastFMSessionKeyPrefix)
+		_, err := tx.Exec(`insert or replace into user_props (user_id, key, value)
+			select ?, 'LastFMSessionKey', ? where exists (select 1 from user where id = ?)`,
+			userID, value, userID)
+		if err != nil {
+			return err
+		}
+	}
+	if err := rows.Err(); err != nil {
