@@ -0,0 +1,126 @@
+'use strict';
+
+class DirectedGraph {
+	constructor() {
+		this._vertices = new Map(); // id -> { label, outbound: Set, inbound: Set }
+		this._arcCount = 0;
+		this._components = null; // cached, invalidated on changes
+	}
+
+	addVertex(id, label) {
+		if (!this._vertices.has(id)) {
+			this._vertices.set(id, { label: label || '', outbound: new Set(), inbound: new Set() });
+			this._components = null;
+		}
+		return this;
+	}
+
+	setLabel(id, label) {
+		if (this._vertices.has(id)) {
+			this._vertices.get(id).label = label;
+		}
+		return this;
+	}
+
+	addArc(fromId, toId) {
+		if (!this._vertices.has(fromId)) {
+			this.addVertex(fromId);
+		}
+		if (!this._vertices.has(toId)) {
+			this.addVertex(toId);
+		}
+
+		const from = this._vertices.get(fromId);
+		if (!from.outbound.has(toId)) {
+			from.outbound.add(toId);
+			this._vertices.get(toId).inbound.add(fromId);
+			this._arcCount++;
+			this._components = null;
+		}
+		return this;
+	}
+
+	_computeComponents() {
+		const parent = new Map();
+
+		const find = (x) => {
+			if (!parent.has(x)) {
+				parent.set(x, x);
+			}
+			if (parent.get(x) !== x) {
+				parent.set(x, find(parent.get(x)));
+			}
+			return parent.get(x);
+		};
+
+		const union = (x, y) => {
+			const px = find(x);
+			const py = find(y);
+			if (px !== py) {
+				parent.set(px, py);
+			}
+		};
+
+		for (const id of this._vertices.keys()) {
+			find(id);
+		}
+
+		for (const [fromId, vertex] of this._vertices) {
+			for (const toId of vertex.outbound) {
+				union(fromId, toId);
+			}
+		}
+
+		const componentMap = new Map();
+		for (const id of this._vertices.keys()) {
+			const root = find(id);
+			if (!componentMap.has(root)) {
+				componentMap.set(root, []);
+			}
+			componentMap.get(root).push(id);
+		}
+
+		this._components = [...componentMap.values()];
+	}
+
+	getComponents() {
+		if (this._components === null) {
+			this._computeComponents();
+		}
+		return this._components;
+	}
+
+	getIsolates() {
+		const isolates = [];
+		for (const [id, vertex] of this._vertices) {
+			if (vertex.outbound.size === 0 && vertex.inbound.size === 0) {
+				isolates.push(id);
+			}
+		}
+		return isolates;
+	}
+
+	getStats() {
+		return {
+			vertices: this._vertices.size,
+			arcs: this._arcCount,
+			components: this.getComponents().length,
+		};
+	}
+
+	getData() {
+		const nodes = [];
+		const edges = [];
+
+		for (const [id, vertex] of this._vertices) {
+			nodes.push({ id, label: vertex.label });
+			for (const toId of vertex.outbound) {
+				edges.push({ from: id, to: toId });
+			}
+		}
+
+		return { nodes, edges };
+	}
+}
+
+module.exports = DirectedGraph;

