+package persistence
+
+import (
+	"context"
+
+	. "github.com/Masterminds/squirrel"
+	"github.com/astaxie/beego/orm"
+	"github.com/navidrome/navidrome/model"
+)
+
+type userPropsRepository struct {
+	sqlRepository
+	userID string
+}
+
+func NewUserPropsRepository(ctx context.Context, o orm.Ormer) model.UserPropsRepository {
+	r := &userPropsRepository{}
+	r.ctx = ctx
+	r.ormer = o
+	r.tableName = "user_props"
+	r.userID = userId(ctx)
+	return r
+}
+
+func (r *userPropsRepository) Put(key string, value string) error {
+	update := Update(r.tableName).Set("value", value).Where(Eq{"user_id": r.userID, "key": key})
+	count, err := r.executeSQL(update)
+	if err != nil {
+		return nil
+	}
+	if count > 0 {
+		return nil
+	}
+	insert := Insert(r.tableName).Columns("user_id", "key", "value").Values(r.userID, key, value)
+	_, err = r.executeSQL(insert)
+	return err
+}
+
+func (r *userPropsRepository) Get(key string) (string, error) {
+	sel := Select("value").From(r.tableName).Where(Eq{"user_id": r.userID, "key": key})
+	resp := struct {
+		Value string
+	}{}
+	err := r.queryOne(sel, &resp)
+	if err != nil {
+		return "", err
+	}
+	return resp.Value, nil
+}
+
+func (r *userPropsRepository) Delete(key string) error {
+	return r.delete(Eq{"user_id": r.userID, "key": key})
+}
