--- /dev/null
+++ b/internal/server/audit/webhook/webhook.go
@@ -0,0 +1,111 @@
+package webhook
+
+import (
+	"bytes"
+	"context"
+	"crypto/hmac"
+	"crypto/sha256"
+	"encoding/hex"
+	"encoding/json"
+	"fmt"
+	"math"
+	"net/http"
+	"time"
+
+	"go.flipt.io/flipt/internal/server/audit"
+	"go.uber.org/zap"
+)
+
+const sinkType = "webhook"
+
+// Sink is the structure in charge of sending Audits to a configured webhook URL.
+type Sink struct {
+	logger             *zap.Logger
+	url                string
+	maxBackoffDuration time.Duration
+	signingSecret      string
+	client             *http.Client
+}
+
+// NewSink is the constructor for a webhook Sink.
+func NewSink(logger *zap.Logger, url string, maxBackoffDuration time.Duration, signingSecret string) audit.Sink {
+	return &Sink{
+		logger:             logger,
+		url:                url,
+		maxBackoffDuration: maxBackoffDuration,
+		signingSecret:      signingSecret,
+		client:             &http.Client{Timeout: 30 * time.Second},
+	}
+}
+
+func (s *Sink) SendAudits(ctx context.Context, events []audit.Event) error {
+	for _, e := range events {
+		if err := s.sendEvent(ctx, e); err != nil {
+			s.logger.Error("failed to send audit event to webhook", zap.String("url", s.url), zap.Error(err))
+		}
+	}
+	return nil
+}
+
+func (s *Sink) sendEvent(ctx context.Context, event audit.Event) error {
+	payload, err := json.Marshal(event)
+	if err != nil {
+		return fmt.Errorf("marshaling audit event: %w", err)
+	}
+
+	// Retry with exponential backoff on transient failures.
+	var lastErr error
+	for attempt := 0; ; attempt++ {
+		req, err := http.NewRequestWithContext(ctx, http.MethodPost, s.url, bytes.NewReader(payload))
+		if err != nil {
+			return fmt.Errorf("creating webhook request: %w", err)
+		}
+		req.Header.Set("Content-Type", "application/json")
+
+		if s.signingSecret != "" {
+			mac := hmac.New(sha256.New, []byte(s.signingSecret))
+			mac.Write(payload)
+			sig := hex.EncodeToString(mac.Sum(nil))
+			req.Header.Set("X-Flipt-Webhook-Signature", sig)
+		}
+
+		resp, err := s.client.Do(req)
+		if err != nil {
+			lastErr = fmt.Errorf("sending webhook request: %w", err)
+		} else {
+			resp.Body.Close()
+			if resp.StatusCode >= 200 && resp.StatusCode < 300 {
+				return nil
+			}
+			lastErr = fmt.Errorf("webhook returned status %d", resp.StatusCode)
+			// Don't retry client errors (4xx) except 429.
+			if resp.StatusCode >= 400 && resp.StatusCode < 500 && resp.StatusCode != http.StatusTooManyRequests {
+				return lastErr
+			}
+		}
+
+		backoff := time.Duration(math.Pow(2, float64(attempt))) * time.Second
+		if backoff > s.maxBackoffDuration {
+			break
+		}
+
+		s.logger.Warn("retrying webhook request", zap.Duration("backoff", backoff), zap.Error(lastErr))
+
+		select {
+		case <-ctx.Done():
+			return ctx.Err()
+		case <-time.After(backoff):
+		}
+	}
+
+	return lastErr
+}
+
+func (s *Sink) Close() error {
+	s.client.CloseIdleConnections()
+	return nil
+}
+
+func (s *Sink) String() string {
+	return sinkType
+}
