diff --git a/internal/server/audit/webhook/webhook.go b/internal/server/audit/webhook/webhook.go
new file mode 100644
index 00000000..380254cf
--- /dev/null
+++ b/internal/server/audit/webhook/webhook.go
@@ -0,0 +1,118 @@
+package webhook
+
+import (
+	"bytes"
+	"context"
+	"crypto/hmac"
+	"crypto/sha256"
+	"encoding/hex"
+	"encoding/json"
+	"net/http"
+	"time"
+
+	"go.flipt.io/flipt/internal/server/audit"
+	"go.uber.org/zap"
+)
+
+const sinkType = "webhook"
+
+const signatureHeader = "x-flipt-webhook-signature"
+
+// Sink POSTs JSON audit events to a configured URL.
+type Sink struct {
+	logger   *zap.Logger
+	client   *http.Client
+	url      string
+	secret   []byte
+	maxBackoff time.Duration
+}
+
+// NewSink creates a webhook sink.
+func NewSink(logger *zap.Logger, url string, maxBackoff time.Duration, signingSecret string) audit.Sink {
+	if maxBackoff == 0 {
+		maxBackoff = 30 * time.Second
+	}
+	secret := []byte(signingSecret)
+	return &Sink{
+		logger:     logger,
+		client:     &http.Client{Timeout: 30 * time.Second},
+		url:        url,
+		secret:     secret,
+		maxBackoff: maxBackoff,
+	}
+}
+
+func (w *Sink) SendAudits(ctx context.Context, events []audit.Event) error {
+	if len(events) == 0 {
+		return nil
+	}
+	payload, err := json.Marshal(events)
+	if err != nil {
+		w.logger.Error("failed to marshal audit events for webhook", zap.Error(err))
+		return err
+	}
+
+	backoff := 100 * time.Millisecond
+	for {
+		req, err := http.NewRequestWithContext(ctx, http.MethodPost, w.url, bytes.NewReader(payload))
+		if err != nil {
+			w.logger.Error("failed to create webhook request", zap.Error(err))
+			return err
+		}
+		req.Header.Set("Content-Type", "application/json")
+		if len(w.secret) > 0 {
+			req.Header.Set(signatureHeader, computeSignature(w.secret, payload))
+		}
+
+		resp, err := w.client.Do(req)
+		if err != nil {
+			w.logger.Warn("webhook request failed", zap.String("url", w.url), zap.Error(err))
+			if backoff < w.maxBackoff {
+				select {
+				case <-ctx.Done():
+					return ctx.Err()
+				case <-time.After(backoff):
+					backoff *= 2
+					continue
+				}
+			}
+			w.logger.Error("webhook failed after retries", zap.String("url", w.url), zap.Error(err))
+			return nil
+		}
+		resp.Body.Close()
+		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
+			return nil
+		}
+		if resp.StatusCode >= 400 && resp.StatusCode < 500 {
+			w.logger.Warn("webhook rejected audit events", zap.String("url", w.url), zap.Int("status", resp.StatusCode))
+			return nil
+		}
+		w.logger.Warn("webhook returned transient error", zap.String("url", w.url), zap.Int("status", resp.StatusCode))
+		if backoff < w.maxBackoff {
+			select {
+			case <-ctx.Done():
+				return ctx.Err()
+			case <-time.After(backoff):
+				backoff *= 2
+				continue
+			}
+		}
+		w.logger.Error("webhook failed after retries", zap.String("url", w.url), zap.Int("status", resp.StatusCode))
+		return nil
+	}
+}
+
+func computeSignature(secret []byte, payload []byte) string {
+	h := hmac.New(sha256.New, secret)
+	h.Write(payload)
+	return "sha256=" + hex.EncodeToString(h.Sum(nil))
+}
+
+func (w *Sink) Close() error {
+	w.client.CloseIdleConnections()
+	return nil
+}
+
+func (w *Sink) String() string {
+	return sinkType
+}
