+package auth
+
+import (
+	"crypto"
+
+	"github.com/gravitational/teleport/api/types"
+	"github.com/gravitational/teleport/lib/auth/native"
+	"github.com/gravitational/teleport/lib/sshutils"
+	"github.com/gravitational/teleport/lib/utils"
+
+	"github.com/gravitational/trace"
+	"golang.org/x/crypto/ssh"
+)
+
+// KeyStore defines an interface for cryptographic key generation, retrieval,
+// and management. Implementations can support different backends such as
+// raw PEM-encoded keys, HSMs, or cloud-based key managers.
+type KeyStore interface {
+	// GenerateRSAKeyPair creates a new RSA key pair and returns the private key
+	// in PEM format and the public key in SSH authorized_keys format.
+	GenerateRSAKeyPair() (privPEM []byte, pubBytes []byte, err error)
+
+	// GetSSHSigner returns an SSH signer from the active key pair in the given
+	// CertAuthority. Only RAW (PEM-encoded) keys are supported by the base
+	// implementation; other backends may support additional key types.
+	GetSSHSigner(ca types.CertAuthority) (ssh.Signer, error)
+
+	// GetTLSSigner returns a crypto.Signer from the active TLS key pair in the
+	// given CertAuthority.
+	GetTLSSigner(ca types.CertAuthority) (crypto.Signer, error)
+
+	// GetJWTSigner returns a crypto.Signer from the active JWT key pair in the
+	// given CertAuthority.
+	GetJWTSigner(ca types.CertAuthority) (crypto.Signer, error)
+
+	// SelectSSHKeyPair returns the active SSH key pair from the CertAuthority
+	// suitable for signing. Returns the first RAW key pair with a private key.
+	SelectSSHKeyPair(ca types.CertAuthority) (*types.SSHKeyPair, error)
+
+	// SelectTLSKeyPair returns the active TLS key pair from the CertAuthority.
+	SelectTLSKeyPair(ca types.CertAuthority) (*types.TLSKeyPair, error)
+
+	// SelectJWTKeyPair returns the active JWT key pair from the CertAuthority.
+	SelectJWTKeyPair(ca types.CertAuthority) (*types.JWTKeyPair, error)
+}
+
+// rawKeyStore implements KeyStore for keys stored in raw PEM-encoded format.
+// This is the default backend and lays the groundwork for future backends
+// like HSMs or cloud-based key managers.
+type rawKeyStore struct{}
+
+// NewRawKeyStore creates a KeyStore implementation that handles raw PEM-encoded keys.
+func NewRawKeyStore() KeyStore {
+	return &rawKeyStore{}
+}
+
+// GenerateRSAKeyPair creates a new RSA key pair using the native key generator.
+func (r *rawKeyStore) GenerateRSAKeyPair() (privPEM []byte, pubBytes []byte, err error) {
+	return native.GenerateKeyPair("")
+}
+
+// GetSSHSigner returns an SSH signer from the active key pair in the CertAuthority.
+func (r *rawKeyStore) GetSSHSigner(ca types.CertAuthority) (ssh.Signer, error) {
+	kp, err := r.SelectSSHKeyPair(ca)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	signer, err := ssh.ParsePrivateKey(kp.PrivateKey)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	return sshutils.AlgSigner(signer, sshutils.GetSigningAlgName(ca)), nil
+}
+
+// GetTLSSigner returns a crypto.Signer from the active TLS key pair.
+func (r *rawKeyStore) GetTLSSigner(ca types.CertAuthority) (crypto.Signer, error) {
+	kp, err := r.SelectTLSKeyPair(ca)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	if len(kp.Key) == 0 {
+		return nil, trace.NotFound("no TLS private key found in CA for %q", ca.GetClusterName())
+	}
+	signer, err := utils.ParsePrivateKey(kp.Key)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	return signer, nil
+}
+
+// GetJWTSigner returns a crypto.Signer from the active JWT key pair.
+func (r *rawKeyStore) GetJWTSigner(ca types.CertAuthority) (crypto.Signer, error) {
+	kp, err := r.SelectJWTKeyPair(ca)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	if len(kp.PrivateKey) == 0 {
+		return nil, trace.NotFound("no JWT private key found in CA for %q", ca.GetClusterName())
+	}
+	signer, err := utils.ParsePrivateKey(kp.PrivateKey)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	return signer, nil
+}
+
+// SelectSSHKeyPair returns the active SSH key pair for signing.
+func (r *rawKeyStore) SelectSSHKeyPair(ca types.CertAuthority) (*types.SSHKeyPair, error) {
+	keyPairs := ca.GetActiveKeys().SSH
+	if len(keyPairs) == 0 {
+		return nil, trace.NotFound("no SSH key pairs found in CA for %q", ca.GetClusterName())
+	}
+	for _, kp := range keyPairs {
+		if kp.PrivateKeyType != types.PrivateKeyType_RAW {
+			continue
+		}
+		if len(kp.PrivateKey) == 0 {
+			continue
+		}
+		return kp, nil
+	}
+	return nil, trace.NotFound("no raw SSH private key found in CA for %q", ca.GetClusterName())
+}
+
+// SelectTLSKeyPair returns the active TLS key pair.
+func (r *rawKeyStore) SelectTLSKeyPair(ca types.CertAuthority) (*types.TLSKeyPair, error) {
+	keyPairs := ca.GetActiveKeys().TLS
+	if len(keyPairs) == 0 {
+		return nil, trace.NotFound("no TLS key pairs found in CA for %q", ca.GetClusterName())
+	}
+	return keyPairs[0], nil
+}
+
+// SelectJWTKeyPair returns the active JWT key pair.
+func (r *rawKeyStore) SelectJWTKeyPair(ca types.CertAuthority) (*types.JWTKeyPair, error) {
+	keyPairs := ca.GetActiveKeys().JWT
+	if len(keyPairs) == 0 {
+		return nil, trace.NotFound("no JWT key pairs found in CA for %q", ca.GetClusterName())
+	}
+	return keyPairs[0], nil
+}

