+'use strict';
+
+const db = require('../database');
+const meta = require('../meta');
+const utils = require('../utils');
+
+const tokens = module.exports;
+
+/**
+ * List all API tokens.
+ * @returns {Promise<Array<{token: string, uid: number, description: string, timestamp: number}>>}
+ */
+tokens.list = async function () {
+	const { tokens: tokenList = [] } = await meta.settings.get('core.api');
+	return tokenList;
+};
+
+/**
+ * Create a new API token with metadata.
+ * @param {Object} data
+ * @param {number} data.uid - User ID the token is tied to
+ * @param {string} [data.description] - Optional description
+ * @returns {Promise<{token: string, uid: number, description: string, timestamp: number}>}
+ */
+tokens.create = async function ({ uid, description }) {
+	const settings = await meta.settings.get('core.api');
+	settings.tokens = settings.tokens || [];
+
+	const newToken = {
+		token: utils.generateUUID(),
+		uid: parseInt(uid, 10),
+		description: description || '',
+		timestamp: Date.now(),
+	};
+	settings.tokens.push(newToken);
+	await meta.settings.set('core.api', settings);
+
+	return newToken;
+};
+
+/**
+ * Retrieve token details by token value.
+ * @param {string} token - The token string
+ * @returns {Promise<{token: string, uid: number, description: string, timestamp: number}|null>}
+ */
+tokens.get = async function (token) {
+	const list = await tokens.list();
+	return list.find(t => t.token === token) || null;
+};
+
+/**
+ * Update token metadata (e.g. description).
+ * @param {string} token - The token string
+ * @param {Object} data - Fields to update
+ * @param {string} [data.description] - New description
+ * @returns {Promise<boolean>} - True if updated
+ */
+tokens.update = async function (token, { description }) {
+	const settings = await meta.settings.get('core.api');
+	settings.tokens = settings.tokens || [];
+
+	const idx = settings.tokens.findIndex(t => t.token === token);
+	if (idx === -1) {
+		return false;
+	}
+
+	if (description !== undefined) {
+		settings.tokens[idx].description = description;
+	}
+	await meta.settings.set('core.api', settings);
+	return true;
+};
+
+/**
+ * Delete a token.
+ * @param {string} token - The token string
+ * @returns {Promise<boolean>} - True if deleted
+ */
+tokens.delete = async function (token) {
+	const settings = await meta.settings.get('core.api');
+	settings.tokens = settings.tokens || [];
+
+	const beforeLen = settings.tokens.length;
+	settings.tokens = settings.tokens.filter(t => t.token !== token);
+	if (beforeLen === settings.tokens.length) {
+		return false;
+	}
+
+	await meta.settings.set('core.api', settings);
+	return true;
+};
+
+/**
+ * Log token usage timestamp.
+ * @param {string} token - The token string
+ */
+tokens.logUsage = async function (token) {
+	await db.sortedSetAdd('tokens:lastSeen', Date.now(), token);
+};
+
+/**
+ * Get last-seen timestamps for tokens.
+ * @param {string[]} tokensList - Array of token strings
+ * @returns {Promise<(number|null)[]>}
+ */
+tokens.getLastSeen = async function (tokensList) {
+	return await db.sortedSetScores('tokens:lastSeen', tokensList);
+};
