+// Copy copies a bundle from a source reference to a destination reference.
+// It returns a Bundle which contains metadata regarding the resulting bundle details.
+// Copy only supports local references (flipt:// scheme); both source and destination
+// must include a tag.
+func (s *Store) Copy(ctx context.Context, srcRef, dstRef Reference) (Bundle, error) {
+	if srcRef.Scheme != SchemeFlipt || dstRef.Scheme != SchemeFlipt {
+		return Bundle{}, fmt.Errorf("copy only supports local references")
+	}
+
+	if srcRef.Reference.Reference == "" {
+		return Bundle{}, fmt.Errorf("source reference must include a tag")
+	}
+	if _, err := digest.Parse(srcRef.Reference.Reference); err == nil {
+		return Bundle{}, fmt.Errorf("source reference must include a tag")
+	}
+
+	if dstRef.Reference.Reference == "" {
+		return Bundle{}, fmt.Errorf("destination reference must include a tag")
+	}
+	if _, err := digest.Parse(dstRef.Reference.Reference); err == nil {
+		return Bundle{}, fmt.Errorf("destination reference must include a tag")
+	}
+
+	srcTarget, err := s.getTarget(srcRef)
+	if err != nil {
+		return Bundle{}, err
+	}
+
+	dstTarget, err := s.getTarget(dstRef)
+	if err != nil {
+		return Bundle{}, err
+	}
+
+	desc, err := oras.Copy(ctx, srcTarget, srcRef.Reference.Reference, dstTarget, dstRef.Reference.Reference, oras.DefaultCopyOptions)
+	if err != nil {
+		return Bundle{}, err
+	}
+
+	manifestBytes, err := content.FetchAll(ctx, dstTarget, desc)
+	if err != nil {
+		return Bundle{}, err
+	}
+	var manifest v1.Manifest
+	if err := json.Unmarshal(manifestBytes, &manifest); err != nil {
+		return Bundle{}, err
+	}
+
+	bundle := Bundle{
+		Digest:     desc.Digest,
+		Repository: dstRef.Repository,
+		Tag:        dstRef.Reference.Reference,
+	}
+	bundle.CreatedAt, err = parseCreated(manifest.Annotations)
+	if err != nil {
+		return Bundle{}, err
+	}
+
+	return bundle, nil
+}
